// Short-film dialogue is generated by the model; no song or separated audio is supplied.
import {h3Ref2Video} from "./h3-ref2video-builder.ts";
import {h3RenderFrames, type Aspect, type EndFrame, type PreviewOptions, type RecommendedResolution, type Resolution, type WorkflowResult} from "../helpers.ts";

export type FilmVideoWorkflowOptions = {
    prompt: string,
    pictures: string[],
    startFrame?: string,
    startClip?: string,
    frames: number,
    seed: number,
    resolution: Resolution,
    aspect?: Aspect,
    preview?: PreviewOptions,
    endFrame?: EndFrame,
    filenamePrefix: string,
}

export const renderFrames = h3RenderFrames
export const recommendedResolution: RecommendedResolution = '1344x768'

export default function h3Ref2VideoFilm(opts: FilmVideoWorkflowOptions): WorkflowResult {
    return h3Ref2Video(opts, {name: 'h3-ref2video-film', turbo: true, sampler: 'euler', scheduler: 'simple', steps: o => o.preview?.steps ?? 8})
}
